let person = {
  name: "Alex",
  age: 25,
  isStudent: true
};

console.log(person.name);   // "Alex"
console.log(person.age);    // 25
console.log(person.isStudent); // true

let car = { brand: "Toyota", year: 2020 };

// Add a new property
car.color = "blue";
console.log(car);  // { brand: "Toyota", year: 2020, color: "blue" }

// Update an existing property
car.year = 2022;
console.log(car.year);  // 2022

// Delete a property
delete car.color;
console.log(car);  // { brand: "Toyota", year: 2022 }

