codeExamples.code:
let user = {
  firstName: "Alex",
  "last name": "Johnson",
  age: 30
};

// Dot notation — works for simple keys
console.log(user.firstName);  // "Alex"
console.log(user.age);       // 30

// Bracket notation — required for keys with spaces
console.log(user["last name"]);  // "Johnson"

// Bracket notation with variables
let field = "age";
console.log(user[field]);  // 30

let settings = {
  theme: "dark",
  fontSize: 14,
  language: "en"
};

let key = "theme";
console.log(settings[key]);  // "dark"

// Dynamic key construction
let property = "font" + "Size";
console.log(settings[property]);  // 14

// Using bracket notation to set properties
settings["maxWidth"] = 1200;
console.log(settings.maxWidth);  // 1200

let user = {
  name: "Alex",
  age: 25,
  city: "New York"
};

const { name, age } = user;
console.log(name);  // "Alex"
console.log(age);   // 25

// Rename variables
const { name: userName, city: location } = user;
console.log(userName);  // "Alex"
console.log(location);  // "New York"

let name = "Alex";
let age = 25;
let role = "student";

// Shorthand: variable name IS the property name
let user = { name, age, role };
console.log(user);  // { name: "Alex", age: 25, role: "student" }

// Default values in destructuring
let config = { host: "localhost" };
const { host, port = 3000, debug = false } = config;
console.log(port);   // 3000 (default)
console.log(debug);  // false (default)

