codeExamples.code:
let person = {
  name: "Alex",
  age: 25,
  job: "developer"
};

console.log(Object.keys(person));
// ["name", "age", "job"]

console.log(Object.values(person));
// ["Alex", 25, "developer"]

console.log(Object.entries(person));
// [["name", "Alex"], ["age", 25], ["job", "developer"]]

let scores = { math: 95, english: 88, science: 92 };

// forEach with entries
Object.entries(scores).forEach(([subject, score]) => {
  console.log(subject + ": " + score);
});
// math: 95
// english: 88
// science: 92

// Filter high scores
let highScores = Object.entries(scores)
  .filter(([subject, score]) => score > 90);
console.log(highScores);
// [["math", 95], ["science", 92]]

