codeExamples.code:
// String to object (parse)
let jsonString = '{"name": "Alex", "age": 25}';
let user = JSON.parse(jsonString);
console.log(user.name);  // "Alex"
console.log(user.age);   // 25

// Object to string (stringify)
let person = { name: "Sam", age: 30 };
let json = JSON.stringify(person);
console.log(json);  // '{"name":"Sam","age":30}'
console.log(typeof json);  // "string"

let data = {
  users: [
    { name: "Alex", age: 25 },
    { name: "Sam", age: 30 }
  ],
  count: 2
};

// Pretty-print with indentation
let pretty = JSON.stringify(data, null, 2);
console.log(pretty);
// {
//   "users": [
//     { "name": "Alex", "age": 25 },
//     { "name": "Sam", "age": 30 }
//   ],
//   "count": 2
// }

// Parse it back
let parsed = JSON.parse(pretty);
console.log(parsed.users[0].name);  // "Alex"

let url = new URL("https://example.com/search?q=javascript&page=2");

// Read parameters
let params = url.searchParams;
console.log(params.get("q"));       // "javascript"
console.log(params.get("page"));    // "2"

// Add a parameter
params.set("sort", "relevance");
console.log(url.href);
// "https://example.com/search?q=javascript&page=2&sort=relevance"

// Remove a parameter
params.delete("page");
console.log(url.href);
// "https://example.com/search?q=javascript&sort=relevance"

// Check if a parameter exists
console.log(params.has("q"));  // true
